// These fields end at a VCF delimiter (or the terminating NUL).  Require the
// whole value to be a decimal integer, so missing or malformed values cannot
// supply a spurious end coordinate.
static int tbx_vcf_int(const char *s, const char *end, int64_t *value)
{
    char *next;
    int overflow = 0;
    const char *digits = s;
    if (digits < end && (*digits == '-' || *digits == '+')) ++digits;
    if (digits == end || *digits < '0' || *digits > '9') return 0;
    *value = hts_str2int(s, &next, 64, &overflow);
    return !overflow && next == end;
}

static const char *tbx_vcf_field_end(const char *s, const char *end, char sep)
{
    const char *next = memchr(s, sep, end - s);
    return next ? next : end;
}

// VCF 4.4 section 3: only these symbolic SVs project SVLEN onto the reference.
// Subtypes inherit the span of their top-level type.  In particular, an INS
// length describes inserted sequence, not reference occupancy.
static int tbx_vcf_is_sv(const char *s, const char *end)
{
    return end - s >= 5 && *s == '<' && end[-1] == '>'
        && (s[4] == '>' || s[4] == ':')
        && (!memcmp(s + 1, "DEL", 3) || !memcmp(s + 1, "DUP", 3)
            || !memcmp(s + 1, "INV", 3) || !memcmp(s + 1, "CNV", 3));
}

static int64_t tbx_vcf_svlen(const char *alt, const char *alt_end,
                             const char *s, const char *end)
{
    int64_t max_svlen = 0;
    while (alt && alt < alt_end && s < end) {
        const char *ae = tbx_vcf_field_end(alt, alt_end, ',');
        const char *se = tbx_vcf_field_end(s, end, ',');
        int64_t svlen;
        // SVLEN is Number=A: even missing values must advance the ALT cursor.
        if (tbx_vcf_is_sv(alt, ae) && tbx_vcf_int(s, se, &svlen)
            && svlen != INT64_MIN) {
            if (svlen < 0) svlen = -svlen; // Pre-4.4 signed lengths
            if (max_svlen < svlen) max_svlen = svlen;
        }
        if (ae == alt_end || se == end) break;
        alt = ae + 1;
        s = se + 1;
    }
    return max_svlen;
}

int tbx_parse1(const tbx_conf_t *conf, size_t len, char *line, tbx_intv_t *intv)
{
    size_t i, b = 0;
    int id = 1;
    char *s;
    const char *alt = NULL, *alt_end = NULL;
    int has_ref_block = 0, len_idx = -1;
    intv->ss = intv->se = 0; intv->beg = intv->end = -1;
    for (i = 0; i <= len; ++i) {
        if (line[i] == '\t' || line[i] == 0) {
            if (id == conf->sc) {
                intv->ss = line + b; intv->se = line + i;
            } else if (id == conf->bc) {
                // here ->beg is 0-based.
                if ((conf->preset&0xffff) == TBX_GAF){
                    // if gaf find the smallest and largest node id
                    char *t;
                    int64_t nodeid = -1;
                    for (s = line + b + 1; s < line + i;) {
                        nodeid = strtoll(s, &t, 0);
                        if(intv->beg == -1){
                            intv->beg = intv->end = nodeid;
                        } else {
                            if(nodeid < intv->beg){
                                intv->beg = nodeid;
                            }

                            if(nodeid > intv->end){
                                intv->end = nodeid;
                            }
                        }
                        s = t + 1;
                    }
                } else {
                    intv->beg = strtoll(line + b, &s, 0);

                    if (conf->bc <= conf->ec) // don't overwrite an already set end point
                        intv->end = intv->beg;

                    if ( s==line+b ) return -1; // expected int

                    if (!(conf->preset&TBX_UCSC))
                        --intv->beg;
                    else if (conf->bc <= conf->ec)
                        ++intv->end;

                    if (intv->beg < 0) {
                        hts_log_warning("Coordinate <= 0 detected. "
                                        "Did you forget to use the -0 option?");
                        intv->beg = 0;
                    }
                    if (intv->end < 1) intv->end = 1;
                }
            } else {
                if ((conf->preset&0xffff) == TBX_GENERIC) {
                    if (id == conf->ec)
                    {
                        intv->end = strtoll(line + b, &s, 0);
                        if ( s==line+b ) return -1; // expected int
                    }
                } else if ((conf->preset&0xffff) == TBX_SAM) {
                    if (id == 6) { // CIGAR
                        int l = 0;
                        char *t;
                        for (s = line + b; s < line + i;) {
                            long x = strtol(s, &t, 10);
                            char op = toupper_c(*t);
                            if (op == 'M' || op == 'D' || op == 'N') l += x;
                            s = t + 1;
                        }
                        if (l == 0) l = 1;
                        intv->end = intv->beg + l;
                    }
                } else if ((conf->preset&0xffff) == TBX_VCF) {
                    if (id == 4) {
                        if (b < i) intv->end = intv->beg + (i - b);
                    } else if (id == 5) {
                        const char *a, *ae;
                        alt = line + b;
                        alt_end = line + i;
                        for (a = alt; a < alt_end; a = ae + 1) {
                            ae = tbx_vcf_field_end(a, alt_end, ',');
                            if ((ae - a == 3 && !memcmp(a, "<*>", 3))
                                || (ae - a == 9 && !memcmp(a, "<NON_REF>", 9)))
                                has_ref_block = 1;
                            if (ae == alt_end) break;
                        }
                    } else if (id == 8) {
                        const char *p, *pe;
                        for (p = line + b; p < line + i; p = pe + 1) {
                            int64_t end;
                            pe = tbx_vcf_field_end(p, line + i, ';');
                            if (pe - p >= 4 && !memcmp(p, "END=", 4)
                                && tbx_vcf_int(p + 4, pe, &end)) {
                                if (end <= intv->beg) {
                                    static int reported = 0;
                                    if (!reported) {
                                        int l = intv->ss ? (int) (intv->se - intv->ss) : 0;
                                        hts_log_warning("VCF INFO/END=%"PRId64" is smaller than POS at %.*s:%"PRIhts_pos"\n"
                                                        "This tag will be ignored. "
                                                        "Note: only one invalid END tag will be reported.",
                                                        end, l >= 0 ? l : 0,
                                                        intv->ss ? intv->ss : "",
                                                        intv->beg + 1);
                                        reported = 1;
                                    }
                                } else if (intv->end < end) {
                                    intv->end = end;
                                }
                            } else if (pe - p >= 6 && !memcmp(p, "SVLEN=", 6)) {
                                int64_t svlen = tbx_vcf_svlen(alt, alt_end, p + 6, pe);
                                // POS is the padding base, before the structural
                                // variant.  Include it in the indexed interval.
                                if (svlen > 0) {
                                    if (svlen >= INT64_MAX - intv->beg) return -1;
                                    end = intv->beg + svlen + 1;
                                    if (intv->end < end) intv->end = end;
                                }
                            }
                            if (pe == line + i) break;
                        }
                    } else if (id == 9 && has_ref_block) {
                        const char *p, *pe;
                        int idx = 0;
                        for (p = line + b; p < line + i; p = pe + 1, ++idx) {
                            pe = tbx_vcf_field_end(p, line + i, ':');
                            if (pe - p == 3 && !memcmp(p, "LEN", 3)) {
                                len_idx = idx;
                                break;
                            }
                            if (pe == line + i) break;
                        }
                    } else if (id > 9 && len_idx >= 0) {
                        const char *p = line + b, *pe;
                        int idx;
                        int64_t ref_len;
                        for (idx = 0; idx < len_idx && p < line + i; ++idx) {
                            pe = tbx_vcf_field_end(p, line + i, ':');
                            p = pe < line + i ? pe + 1 : pe;
                        }
                        pe = tbx_vcf_field_end(p, line + i, ':');
                        // VCF 4.5 sections 1.6.2 and 5.5: LEN includes POS;
                        // take the longest reference block across all samples.
                        if (tbx_vcf_int(p, pe, &ref_len) && ref_len > 0) {
                            if (ref_len > INT64_MAX - intv->beg) return -1;
                            if (intv->end < intv->beg + ref_len)
                                intv->end = intv->beg + ref_len;
                        }
                    }
                }
            }
            b = i + 1;
            ++id;
        }
    }
    if (intv->ss == 0 || intv->se == 0 || intv->beg < 0 || intv->end < 0) return -1;
    return 0;
}

static inline int get_intv(tbx_t *tbx, kstring_t *str, tbx_intv_t *intv, int is_add)
{
    if (tbx_parse1(&tbx->conf, str->l, str->s, intv) == 0) {
        int c = *intv->se;
        *intv->se = '\0';
        if ((tbx->conf.preset&0xffff) == TBX_GAF){
            intv->tid = 0;
        } else {
            intv->tid = get_tid(tbx, intv->ss, is_add);
        }
        *intv->se = c;
        if (intv->tid < 0) return -2;  // get_tid out of memory
        return (intv->beg >= 0 && intv->end >= 0)? 0 : -1;
    } else {
        char *type = NULL;
        switch (tbx->conf.preset&0xffff)
        {
            case TBX_SAM: type = "TBX_SAM"; break;
            case TBX_VCF: type = "TBX_VCF"; break;
            case TBX_GAF: type = "TBX_GAF"; break;
            case TBX_UCSC: type = "TBX_UCSC"; break;
            default: type = "TBX_GENERIC"; break;
        }
        if (hts_is_utf16_text(str))
            hts_log_error("Failed to parse %s: offending line appears to be encoded as UTF-16", type);
        else
            hts_log_error("Failed to parse %s: was wrong -p [type] used?\nThe offending line was: \"%s\"",
                type, str->s);
        return -1;
    }
}

